{
  "title": "绝情谷迷局",
  "scene": "你站在绝情谷的边缘，谷内弥漫着淡淡的雾气，谷底隐约可见一座破旧的石桥。远处，一名黑衣人正在石桥上徘徊，似乎在等待着什么。谷边的石壁上刻着一行字迹：‘绝情谷之谜，非智者不能解。’谷底传来微弱的灯火摇曳声，似乎有机关正在启动。",
  "goal": "找到通往谷底的秘密机关，解开谜题，揭开绝情谷的真相。",
  "choices": [
    {
      "id": "A",
      "text": "走近黑衣人，试图与他交谈。",
      "outcome": "你走近黑衣人，他似乎没有察觉，只是继续沿着石桥走动，而你隐约听到山谷深处传来细微的轻功声。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "观察石壁上的字迹，试图解读其中的含义。",
      "outcome": "你仔细观察刻在石壁上的字迹，发现其中隐含着一些线索，比如“四”“八”“一”“三”，但无法直接看出其含义。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "前往石桥下，尝试找到机关的入口。",
      "outcome": "你来到了石桥的下方，发现石桥旁边有一块不平整的石头，轻轻一推，石头下方竟升起一条隐秘的石梯，通往谷底。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
